import http from 'k6/http';
import { check } from 'k6';

export const options = {
  vus: 1,
  iterations: 1,
};

export default function () {
  const baseUrl = __ENV.BASE_URL;
  const jsonHeaders = { 'Content-Type': 'application/json' };

  // 1. POST /login - sets session cookie via k6's per-VU cookie jar
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: jsonHeaders }
  );
  check(loginRes, { 'login status 2xx': (r) => r.status >= 200 && r.status < 300 });

  // Extract the csrf token from login response JSON
  const csrfToken = loginRes.json('csrf');

  // 2. GET /products - required before cart; session cookie sent automatically
  const productsRes = http.get(`${baseUrl}/products`);
  check(productsRes, { 'products status 2xx': (r) => r.status >= 200 && r.status < 300 });

  // 3. POST /cart - requires X-CSRF-Token header
  const cartHeaders = Object.assign({}, jsonHeaders, { 'X-CSRF-Token': csrfToken });
  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    { headers: cartHeaders }
  );
  check(cartRes, { 'cart status 2xx': (r) => r.status >= 200 && r.status < 300 });

  // 4. POST /checkout - requires X-CSRF-Token header; one checkout per session
  const checkoutHeaders = Object.assign({}, jsonHeaders, { 'X-CSRF-Token': csrfToken });
  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    { headers: checkoutHeaders }
  );
  check(checkoutRes, { 'checkout status 2xx': (r) => r.status >= 200 && r.status < 300 });
}
